What is the time complexity of this function, where n = len(s)?

def longest(s):
    seen, left, best = {}, 0, 0
    for r, ch in enumerate(s):
        if ch in seen and seen[ch] >= left:
            left = seen[ch] + 1
        seen[ch] = r
        best = max(best, r - left + 1)
    return best

